def compute(vars):
    denominator = vars["v2"]
    if denominator == 0:
        return None

    ratio = vars["v1"] / denominator

    return {
        "value": round(ratio, 3),
        "trace": {
            "numerator": vars["v1"],
            "denominator": denominator,
            "ratio": ratio,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "amount"
            }
        }
    }
